render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, y = cfg$y), c("x", "y")); n <- 100; counts <- round(n * data[[cfg$y]] / sum(data[[cfg$y]])); counts[length(counts)] <- n - sum(counts[-length(counts)]); cells <- data.frame(id = seq_len(n)); cells$group <- rep(as.character(data[[cfg$x]]), counts); cells$col <- (cells$id - 1) %% 10; cells$row <- 9 - ((cells$id - 1) %/% 10); p <- ggplot2::ggplot(cells, ggplot2::aes(x = col, y = row, fill = group)) + ggplot2::geom_tile(colour = "white", linewidth = 0.35) + ggplot2::coord_equal() + ggplot2::scale_x_continuous(NULL, breaks = NULL) + ggplot2::scale_y_continuous(NULL, breaks = NULL) + ggplot2::theme_void() + ggplot2::labs(title = cfg$title %||% "组成比例", fill = cfg$x); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
